// Each code point includes lone surrogates. Each block starts with FNV offset 2166136261.
// Feed one UTF-16 '0'/'1' unit per result, in u, v order for each code point.
const pattern0 = /^\p{General_Category=Other_Symbol}$/u;
const pattern1 = /^\p{General_Category=Other_Symbol}$/v;
const expected: number[] = [
  0xe3e36581, 0xbde3a543, 0x191b5c39, 0xf50e9f65, 0x65344645, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xebd01eef, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0x637022e3,
  0xb499b953, 0xb452a5c9, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0x9e82ca77, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0x126a04bf, 0x40be4f99, 0xb28b524b, 0x3bf73183, 0xb3362361,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
  0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5, 0xfa431dc5,
];
assert.sameValue(expected.length, 64);
for (let block = 0x000000; block < 0x040000; block += 4096) {
  let hash = 2166136261;
  for (let cp = block; cp < block + 4096; cp++) {
    const input = String.fromCodePoint(cp);
    hash = Math.imul(hash ^ (pattern0.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (pattern1.test(input) ? 0x31 : 0x30), 16777619) >>> 0;
  }
  assert.sameValue(hash, expected[(block - 0x000000) / 4096], "General_Category=Other_Symbol block U+" + block.toString(16));
}
